"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[261],{5495(e){e.exports=JSON.parse('{"title":"\ud504\ub860\ud2b8\uc5d4\ub4dc \ub450 \uac1c\uc758 \ud2b8\ub9ac & Tree shaking\uc774 \ubb54\ub370","date":"2024-04-23","coverUrl":null,"html":"<h2 data-notion-block-id=\\"e4fc7fe7-d3e6-4687-8650-841e73f19b67\\" id=\\"e4fc7fe7-d3e6-4687-8650-841e73f19b67\\">CSS \ud2b8\ub9ac\uc640 DOM \ud2b8\ub9ac\uac00 \ub2e4\ub978 \uc704\uce58\uc5d0 \uc788\ub294 \uac83\uc740 \ubb38\uc81c\uac00 \ub41c\ub2e4.</h2><a href=\\"https://danielnagy.me/posts/Post_jt4adn0o5bnr\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://danielnagy.me/posts/Post_jt4adn0o5bnr</a><p data-notion-block-id=\\"f5519b78-3aec-4b3d-9ca5-99d01f45caeb\\"><b>\uc2ec\uc724\uc12d</b>: \ud765\ubbf8\ub85c\uc6b4 CSS-in-JS\uc640 Utility-First CSS\uc5d0 \ub300\ud55c \uc790\uc2e0\uc758 \uad00\uc810\uc744 \ub4dc\ub7ec\ub0b8 \uae00\uc785\ub2c8\ub2e4. CSS-in-JS(styled-components, emotion)\uc758 CSS\uc758 \uc120\ud0dd\uc790\ub97c \uacb0\uad6d \uc0ac\uc6a9\ud574\uc57c \ud55c\ub2e4\ub294 \uc810, Utility-First CSS\uc5d0\uc11c \uae30\uc874 CSS \uae30\ub2a5\ub4e4\uc744 \ubaa8\ub450 \uc0ac\uc6a9\ud558\uc9c0 \ubabb\ud55c\ub2e4\ub294 \uc810\uc744 \ub9d0\ud558\uba74\uc11c UI \ud504\ub808\uc784\uc6cc\ud06c\uc5d0\uc11c CSS\uae30\ub2a5\uc744 \ubaa8\ubc29\ud574\uc11c \uc778\ub77c\uc778 \uc2a4\ud0c0\uc77c\ub9c1\uc744 \ud558\ub294 \uac83\uc740 \uc5b4\ub5bb\ub0d0\ub294 \uad00\uc810\uc744 \uc81c\uc2dc\ud569\ub2c8\ub2e4. \ud558\uc9c0\ub9cc CSS\uc758 \uae30\ub2a5\uc744 \ubaa8\ubc29\ud55c JS\ub294 \uc131\ub2a5\uc744 \ubcf4\uc7a5\ubc1b\uc9c0 \ubabb\ud560 \ubfd0\ub354\ub7ec \uc5ed\uc2dc CSS\uc758 \ub9ce\uc740 \uae30\ub2a5\uc744 \ud3ec\uae30\ud558\uac8c \ub418\uae30 \ub54c\ubb38\uc5d0 \uc5ed\uc2dc \ub3c4\uc785\uc744 \uc2e0\uc911\ud558\uac8c \ud574\uc57c \ud569\ub2c8\ub2e4(\ub313\uae00\uc5d0\uc11c \uc774\ub97c \uc9c0\uc801\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4!). CSS-in-JS\uc640 Utility-First CSS\uc5d0 \ub300\ud574 \uad81\uae08\ud558\uc2e0 \ubd84\uc740 <a href=\\"https://tech.kakao.com/2022/05/20/on-demand-atomic-css-library/\\">\uad00\ub828 \uae00</a>\uc744 \ubcf4\uc138\uc694 \ud83d\ude42</p><h2 data-notion-block-id=\\"a0608cf9-07a8-4413-95e5-f535e3811bff\\" id=\\"a0608cf9-07a8-4413-95e5-f535e3811bff\\">Tree shaking\uc774 \ubb54\ub370</h2><a href=\\"https://github.com/orgs/web-infra-dev/discussions/17\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/orgs/web-infra-dev/discussions/17</a><p data-notion-block-id=\\"77ab0939-1bc3-4a4e-9379-395752daa40c\\"><b>\uc2ec\uc724\uc12d</b>: Rspack\ud300\uc5d0\uc11c Tree Shaking\ub97c \uc815\uc758\ud558\uace0 webpack\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uc9c4\ud589\ub418\ub294\uc9c0 \uc54c\ub824\uc90d\ub2c8\ub2e4. \ud504\ub860\ud2b8\uc5d4\ub4dc\uc5d0\uc11c\ub294 \uc0ac\uc6a9\uc790\uc5d0\uac8c \ucf54\ub4dc\uac00 \uadf8\ub300\ub85c \ub178\ucd9c\ub418\ubbc0\ub85c \ub9e4\uc6b0 \uc911\uc694\ud55c \uac1c\ub150\uc785\ub2c8\ub2e4. \uc5b4\ub5a4 \uc18d\uc131\uc744 \uc81c\uacf5\ud558\ub294\uc9c0, \uadf8\uc5d0 \ub530\ub77c \uc911\uc694\ud55c \ub0b4\ubd80 \ucf54\ub4dc\uac00 \ub178\ucd9c\ub420\uc9c0 \uc544\ub2d0\uc9c0 \uacb0\uc815\ud558\ub2c8\uae4c\uc694.</p><h2 data-notion-block-id=\\"2cbf8614-f749-4e2f-aa50-e50991637348\\" id=\\"2cbf8614-f749-4e2f-aa50-e50991637348\\">\ud658\uacbd \ubcc0\uc218 \uc124\uc815\uc758 \uc9c0\uc18d \uac00\ub2a5\ud55c \ud574\uacb0\ucc45</h2><a href=\\"https://massimilianomirra.com/notes/the-frontend-process-env-time-bomb-plus-a-sustainable-definition-of-fixed\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://massimilianomirra.com/notes/the-frontend-process-env-time-bomb-plus-a-sustainable-definition-of-fixed</a><p data-notion-block-id=\\"722a0464-4229-4a11-83ac-5c53f4835608\\"><b>\uc2ec\uc724\uc12d</b>: \ud658\uacbd\ubcc0\uc218 \uc124\uc815\uc744 \ubc30\ud3ec\ud558\uae30 \uc804\uc5d0 \uae4c\uba39\uc744 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uadf8\ub97c \ubc29\uc9c0\ud558\uae30 \uc704\ud574 \ubb38\uc81c\ub97c \uc815\uc758\ud558\uace0 \uc774\ub97c zod\uc640 \uba85\ub839\uc5b4\ub85c \uc774\ub97c \ud574\uacb0\ud558\ub294 \ubc29\uc2dd\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4. <code>Context</code>\ub97c \uc0ac\uc6a9\ud558\ub294 \uac83\uc744 \uc81c\uc678\ud558\uace0\ub294 \uc2e4\uc81c\ub85c \uc801\uc6a9\ud574\ubcfc\ub9cc\ud55c \ubc29\uc2dd\uc785\ub2c8\ub2e4. \ub610\ub294 <a href=\\"https://www.totaltypescript.com/how-to-strongly-type-process-env#solution-2-validate-it-at-runtime-with-t3-env\\">\uc774\uc640 \uad00\ub828\ub41c \ud328\ud0a4\uc9c0</a>\ub97c \uc0ac\uc6a9\ud560 \uc218\ub3c4 \uc788\uaca0\uc8e0. \uc544\ub2c8\uba74 \ubc88\ub4e4\ub9c1 \uc124\uc815\uc5d0\uc11c Define\uc5d0 \ub4e4\uc5b4\uac08 \uac12\uc758 \uc720\ud6a8\uc131 \uac80\uc0ac\ub97c \ud558\ub294 \ubc29\ubc95\ub3c4 \uc788\uaca0\uc8e0(<a href=\\"https://vitejs.dev/config/shared-options.html#define\\">Vite</a>, <a href=\\"https://webpack.kr/plugins/define-plugin/\\">Webpack</a>). \uadf8\ub798\uc57c \ud658\uacbd\ubcc0\uc218\ub97c \ud1b5\ud574 \ud2b8\ub9ac \uc170\uc774\ud0b9\uc73c\ub85c \uc6d0\uce58 \uc54a\uc740 \ucf54\ub4dc\uac00 \ub4e4\uc5b4\uac00\ub294 \uac83\uc744 \ubc29\uc9c0\ud560 \uc218 \uc788\uaca0\uc8e0.</p><h2 data-notion-block-id=\\"cbb13f25-4ada-4df4-8188-72fbd4fb84b4\\" id=\\"cbb13f25-4ada-4df4-8188-72fbd4fb84b4\\">TypeScript 5.5\uc758 \uc2e0\uae30\ub2a5: \ud0c0\uc785 \uc220\uc5b4 \ucd94\ub860</h2><a href=\\"https://www.totaltypescript.com/type-predicate-inference\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.totaltypescript.com/type-predicate-inference</a><a href=\\"https://effectivetypescript.com/2024/04/16/inferring-a-type-predicate/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://effectivetypescript.com/2024/04/16/inferring-a-type-predicate/</a><p data-notion-block-id=\\"3a24822b-542e-4d6c-ab08-2f46c26838fd\\"><b>\uc2ec\uc724\uc12d</b>: \uccab\ubc88\uc9f8 \uae00\uc740 \uc774\uc804\uc5d0 \uc18c\uac1c\ud588\ub358 <a href=\\"https://ones-to-watch.ethansup.net/news/post/8b8e4348-60f9-477e-9892-e7dfdf611fe0#db6b486a-ac4d-43cd-889c-7e41f5be3ec6\\">\ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8\uc758 \ucd94\ub860 \ubc29\uc2dd</a>\uc744 \uc791\uc131\ud55c \uc800\uc790\uac00 \ud0c0\uc785 \uc220\uc5b4 \ucd94\ub860 \uae30\ub2a5\uc744 \ucd94\uac00\ud55c PR\uc744 \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774\ud6c4 Type Guard\ub97c \ub354 \uc27d\uac8c \uc4f8 \uc218 \uc788\uaca0\ub124\uc694. \ub450 \ubc88\uc9f8 \uae00\uc740 \uc790\uc2e0\uc774 \uae30\ub2a5 \ucd94\uac00 PR\uc744 \uc0dd\uc131\ud558\uae30 \uae4c\uc9c0\uc758 \uc77c\uc9c0\ub97c \uc801\uc740 \uac83\uc785\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c \ucd94\ub860\uc744 \uc5b4\ub5bb\uac8c \ub2ec\uc131\ud588\ub294\uc9c0\ub97c \ubcfc \uc218\ub3c4 \uc788\uc9c0\ub9cc \uc624\ud508\uc18c\uc2a4\uc5d0\uc11c \uae30\uc5ec\ud558\uae30\uae4c\uc9c0\uc758 \uacfc\uc815\ub3c4 \ud55c \ubc88 \ubcf4\uace0 \uc5b4\ub824\uc6b4 \uc77c\uc774 \uc544\ub2c8\ub77c\ub294 \uac83\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc624\ud508\uc18c\uc2a4\uc5d0 \uae30\uc5ec\ud558\ub294 \uac83\uc5d0 \ub450\ub824\uc6c0\uc744 \uac16\uc9c0 \ub9c8\uc138\uc694!</p><h2 data-notion-block-id=\\"9f74a592-7ded-41eb-be2f-a6c95c890774\\" id=\\"9f74a592-7ded-41eb-be2f-a6c95c890774\\">CSS-in-JS\uc758 \ubc1c\uc804\uacfc SSR\uc758 \ucda9\ub3cc</h2><a href=\\"https://www.joshwcomeau.com/react/css-in-rsc/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.joshwcomeau.com/react/css-in-rsc/</a><p data-notion-block-id=\\"96e6c3fb-69bb-4cb9-a78f-70c804622e32\\"><b>\uc2ec\uc724\uc12d</b>: \uae30\uc874 CSS-in-JS\uc758 \uc791\ub3d9\ubc29\uc2dd\uacfc SSR, React Server Components\uc758 \ucda9\ub3cc\uacfc \ucd5c\uc2e0 CSS-in-JS\uc774 \uc774\ucda9\ub3cc \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub294 \ubc29\uc2dd\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4. \uae30\uc874 CSS-in-JS\uac00 \uc774\ub97c \ud574\uacb0\ud558\uc9c0 \ubabb\ud558\ub294 \uc774\uc720\ub97c \uc790\uc138\ud558\uac8c \uc124\uba85\ud558\uace0 \ud604\uc7ac CSS-in-JS\uc774 \uac00\uace0 \uc788\ub294 \ubc29\ud5a5\uc131\uc744 \uc124\uba85\ud558\ubbc0\ub85c CSS-in-JS\uc5d0 \uad00\uc2ec\uc788\ub294 \ubd84\ub4e4\uc740 \ubaa8\ub450 \ubcf4\uc2dc\uae38 \ubc14\ub78d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"f29e4a24-df9a-40b1-adc6-3d1fd524a9a4\\" id=\\"f29e4a24-df9a-40b1-adc6-3d1fd524a9a4\\">Protected Route\ub97c \uc704\ud574 \ubbf8\ub4e4\uc6e8\uc5b4\ub97c \uc0ac\uc6a9\ud558\uc9c0 \ub9c8\uc138\uc694.</h2><a href=\\"https://pilcrowonpaper.com/blog/middleware-auth/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://pilcrowonpaper.com/blog/middleware-auth/</a><p data-notion-block-id=\\"9c22537a-3f66-4bd2-9849-583473d4d814\\"><b>\uc2ec\uc724\uc12d</b>: Protected middleware\uac00 \uc798\ubabb\ub41c \ucd94\uc0c1\ud654\uc774\uba70, <a href=\\"https://www.cloudflare.com/ko-kr/learning/access-management/role-based-access-control-rbac/\\">RBAC</a>\ub85c \uae30\ub2a5\uc744 \ud655\ub300\ud55c\ub2e4\uba74 \uc774\ub294 \ub108\ubb34 \ubcf5\uc7a1\ud574\uc9c4\ub2e4\ub77c\uace0 \uc800\uc790\ub294 \ub9d0\ud569\ub2c8\ub2e4. \uadf8\ub9ac\uace0 \uae30\ub2a5 \ucd94\uac00\uc2dc \ub514\ubc84\uae45\uacfc \ud14c\uc2a4\ud2b8\ub97c \uc704\ud574 \uc801\uc808\ud55c \ucd94\uc0c1\ud654\uc758 \uc911\uc694\uc131\uc744 \uac15\uc870\ud569\ub2c8\ub2e4. \ud56d\uc0c1 \uc0dd\uac01\ud558\uc9c0\ub9cc \\"\uc801\uc808\ud558\uac8c\\"\ub294 \uc5b4\ub835\uc2b5\ub2c8\ub2e4. \uc774\uc804\uc5d0 \uc18c\uac1c\ud588\ub358 <a href=\\"https://ones-to-watch.ethansup.net/news/post/f51019e1-e38c-4b60-a636-aab2334f6e8b#ec85017c-c8bc-46e1-abbe-e69801686efa\\">\ucd94\uc0c1\ud654\ub294 \uc801\uc808\ud558\uac8c</a> \uae00\ub3c4 \ub2e4\uc2dc \ubcf4\ub294 \uac83\ub3c4 \ub098\uc058\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4!</p><h2 data-notion-block-id=\\"e499ff0b-cdcc-49a0-bd4e-43f1ea6bc90b\\" id=\\"e499ff0b-cdcc-49a0-bd4e-43f1ea6bc90b\\"><code>any</code>\ub294 \uc5b8\uc81c \uc368\uc57c \ud558\ub098\uc694?</h2><a href=\\"https://www.totaltypescript.com/any-considered-harmful\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.totaltypescript.com/any-considered-harmful</a><p data-notion-block-id=\\"9ff4b163-3140-4a0f-85b2-185aeb235e51\\"><b>\uc2ec\uc724\uc12d</b>: <code>any</code>\ub97c \uc368\uc57c \ud558\ub294 \ub54c\ub294 \ubd84\uba85\ud788 \uc788\uc2b5\ub2c8\ub2e4. React\ub97c \ubc30\uc6b8 \ub54c \uc720\uba85\ud55c \uae00\uc778 <a href=\\"https://kentcdodds.com/blog/usememo-and-usecallback\\">\uc5b8\uc81c </a><a href=\\"https://kentcdodds.com/blog/usememo-and-usecallback\\"><code>useMemo</code></a><a href=\\"https://kentcdodds.com/blog/usememo-and-usecallback\\">\uc640 </a><a href=\\"https://kentcdodds.com/blog/usememo-and-usecallback\\"><code>useCallback</code></a><a href=\\"https://kentcdodds.com/blog/usememo-and-usecallback\\">\uc744 \uc368\uc57c \ud558\ub098\uc694?</a>\uc5d0\uc11c\ub3c4 \ub300\ubd80\ubd84\uc758 \uacbd\uc6b0\uc5d0\uc11c \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub418\uc9c0\ub9cc \uc0ac\uc6a9\ucc98\ub294 \uc788\ub2e4\uace0 \ubc1d\ud788\uc8e0. \ubb3c\ub860 \uc7a5\ub2e8\uc810\uc744 \uc800\uc6b8\uc9c8\ud558\uba74\uc11c \uc368\uc57c\ud558\uc9c0\ub9cc\uc694.</p><h2 data-notion-block-id=\\"62955a06-43ba-497e-94ae-faec0080eead\\" id=\\"62955a06-43ba-497e-94ae-faec0080eead\\">\uc815\ub9d0 \uc7ac\uc0ac\uc6a9 \uac00\ub2a5\ud55c Button \ub9cc\ub4e4\uae30</h2><a href=\\"https://react-japan.dev/en/blog/empathetic-coding-button-component\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://react-japan.dev/en/blog/empathetic-coding-button-component</a><p data-notion-block-id=\\"eb044e7b-e3c6-45f8-9b71-0c8314223e94\\"><b>\uc2ec\uc724\uc12d</b>: \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc5d0\uc11c, \uadf8\uac8c \uc544\ub2c8\ub354\ub77c\ub3c4 \uac04\ub2e8\ud55c \ucef4\ud3ec\ub10c\ud2b8\ub97c \uc7ac\uc0ac\uc6a9 \uac00\ub2a5\ud558\uac8c \ub9cc\ub4e4\ub77c\uace0 \ud558\uba74 \uc5b4\ub5bb\uac8c \uc811\uadfc\ud574\uc57c \ud560\uc9c0 \ubaa8\ub974\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc740 \ub2e8\uacc4\ubcc4\ub85c \uc7ac\uc0ac\uc6a9 \uac00\ub2a5\ud55c \ucef4\ud3ec\ub10c\ud2b8\ub97c \ub9cc\ub4e4\uba74\uc11c \ubbf8\ub798\ub97c \uc704\ud574 \uc5b4\ub5bb\uac8c \uc811\uadfc\ud574\uc57c \ud558\ub294\uc9c0, \ud604\uc7ac \ub2e8\uacc4\uc758 \ud55c\uacc4\uc810\uc740 \uc5b4\ub5bb\uac8c \ub418\ub294\uc9c0 \ub9d0\ud574\uc90d\ub2c8\ub2e4. \uacf5\uc6a9 \ucef4\ud3ec\ub10c\ud2b8\ub85c \ubd84\ub9ac\ud560 \ub54c \uace0\ub824\ud574\uc57c \ud560 \uc810\uc744 \uc81c\uc2dc\ud558\ubbc0\ub85c \ub098\uc911\uc5d0 \uacf5\uc6a9 \ucef4\ud3ec\ub10c\ud2b8\ub97c \ub9cc\ub4e4 \ub54c \uc801\uc6a9\ud558\uba74 \uc88b\uc2b5\ub2c8\ub2e4. \uc774 \ucef4\ud3ec\ub10c\ud2b8\ub97c \ub9cc\ub4e4\uba74\uc11c <a href=\\"https://react-japan.dev/en/blog/empathetic-coding\\">\uacf5\uac10\ud615 \uc811\uadfc\ubc29\uc2dd</a>\uc774\ub77c\ub294 \ucca0\ud559\ub3c4 \uc81c\uc2dc\ud558\ub2c8 \uc774 \uac83\ub3c4 \ubcf4\uba74 \ucf54\ub529\uc744 \ud560 \ub54c \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4(Kent C. Dodds.\uc528\uac00 <a href=\\"https://kentcdodds.com/blog/aha-programming\\">AHA</a>\ub97c \uc81c\uc2dc\ud55c \uac83\ucc98\ub7fc\uc694!).</p><h2 data-notion-block-id=\\"4af3edd0-7fc1-41c9-9ecc-3cf85b356328\\" id=\\"4af3edd0-7fc1-41c9-9ecc-3cf85b356328\\">\uc6b0\ub9ac Qwik \uc6d4\ud074 \uc544\ub2d9\ub2c8\ub2e4</h2><a href=\\"https://outshift.cisco.com/blog/qwik-vs-nextjs\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://outshift.cisco.com/blog/qwik-vs-nextjs</a><p data-notion-block-id=\\"6b8cc312-decd-44a9-ad48-ce55a06c72d4\\"><b>\uc2ec\uc724\uc12d</b>: \ub274\uc2a4\ub808\ud130 \ucd08\uae30 \ubc84\uc804\uc5d0\uc11c Hydration\uc758 \ubc1c\uc804\uc744 \uc124\uba85\ud558\uba74\uc11c <a href=\\"https://dev.to/this-is-learning/resumability-wtf-2gcm\\">Resumablity</a> \uac1c\ub150\uc744 \uac00\uc838\uc628 \uac83\uc774 \uc0dd\uac01\ub098\ub124\uc694. \ud574\ub2f9 \uac1c\ub150\uc744 \uc801\uc6a9\ud55c Qwik\uc758 \uc7a5\uc810\uacfc Next.js\ub300\uc2e0 \uc120\ud0dd\ud55c \uc774\uc720\ub97c \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc88b\uc740 \ud504\ub808\uc784\uc6cc\ud06c\uc774\uc9c0\ub9cc.. \uc544\uc9c1 \uad00\uc2ec\ub9cc \uac00\uc9c0\ub294 \uac83\uc774 \uc88b\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"3dfc1731-c4dd-49fa-a000-48c37df967a2\\" id=\\"3dfc1731-c4dd-49fa-a000-48c37df967a2\\">CSS \uc6b0\uc120\uc21c\uc704 \uc18c\uac1c</h2><a href=\\"https://piccalil.li/blog/a-primer-on-the-cascade-and-specificity/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://piccalil.li/blog/a-primer-on-the-cascade-and-specificity/</a><p data-notion-block-id=\\"1edb1355-c3b7-44ba-bfb9-ff41f4768c46\\">CSS \ucd08\ubcf4\uc790\ub97c \uc704\ud55c CSS selector\uc640 \uc18d\uc131\uc5d0 \ub530\ub978 \uc6b0\uc120\uc21c\uc704\ub97c \uc18c\uac1c\ud569\ub2c8\ub2e4. \uac00\ubccd\uac8c \ubcfc\ub9cc\ud55c \uc8fc\uc81c\ub124\uc694.</p><h2 data-notion-block-id=\\"c077f857-313f-4239-be72-5af7caa5dce0\\" id=\\"c077f857-313f-4239-be72-5af7caa5dce0\\">\uc640 \uc2e0\uc81c\ud488!</h2><a href=\\"https://nextjs.org/blog/next-14-2\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nextjs.org/blog/next-14-2</a><a href=\\"https://github.com/facebook/react/pull/28843\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/facebook/react/pull/28843</a><p data-notion-block-id=\\"bb8819fc-47f7-4300-a805-b4397aee98fe\\">React\uc758 \uc77c\ubd80 \uae30\ub2a5 deprecated\ub97c \uc54c\ub9ac\uae30 \uc704\ud55c \ub9c8\uc774\ub108 \ud328\uce58, Next.js\uc758 DX, \uc131\ub2a5 \ud5a5\uc0c1 \ud328\uce58\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"d15a490f-3bf0-4318-b765-e8b9fe7ee7bd\\" id=\\"d15a490f-3bf0-4318-b765-e8b9fe7ee7bd\\">JSR\uc740 \uc5b4\ub5bb\uac8c \uad6c\uc131\ub418\uc5c8\ub294\uac00</h2><a href=\\"https://deno.com/blog/how-we-built-jsr\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://deno.com/blog/how-we-built-jsr</a><p data-notion-block-id=\\"c2915691-db90-45a0-8d75-cf3abaf9adeb\\">deno\ud300\uc5d0\uc11c \ube60\ub978 \uc751\ub2f5, \uc11c\ubc84\uc758 \uc548\uc815\uc131, npm\uacfc \uc0c1\ud638\uc6b4\uc6a9\uc131\uc744 \uc704\ud574 \uc5b4\ub5a4 \uac83\uc744 \uace0\ubbfc\ud588\ub294\uc9c0, \uc5b4\ub5bb\uac8c JSR\uc744 \ub9cc\ub4e4 \ub54c \uc801\uc6a9\ud588\ub294\uc9c0\ub97c \ub9d0\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><p data-notion-block-id=\\"02854dc3-2347-426e-b00a-d701d890df66\\"></p>"}')}}]);